def verifier_go_machine(chemin_registre: Path, chemin_garde: Path, go_id: str, aujourd_hui: dt.date) -> dict:
    """Variante (a) : le GO de la machine, même garde de `main`, montant exactement 35 USD."""
    if go_id == GO_ATTENDU or not re.fullmatch(r"GO-\d{4}-\d{2}-\d{2}-\d{2}", go_id or ""):
        raise Refus(f"GO de la machine {go_id!r} : identifiant exact, distinct de {GO_ATTENDU}, exigé")
    garde = charger_garde(chemin_garde, chemin_registre)
    tampon = io.StringIO()
    try:
        with redirect_stderr(tampon):
            garde.decider(f"GO_ID={go_id} vastai create instance 0", aujourd_hui)
    except SystemExit as e:
        if e.code not in (0, None):
            raise Refus(f"garde de main (GO de la machine) : {tampon.getvalue().strip()}") from None
    for cellules in lignes_du_go(chemin_registre, go_id):
        mm = MONTANT.match(cellules[4])
        if not mm or abs(float(mm.group(1).replace(",", ".")) - MONTANT_GO_MACHINE_USD) > 1e-9:
            raise Refus(f"{go_id} : plafond « {cellules[4]} » au lieu de exactement {MONTANT_GO_MACHINE_USD:g} USD")
    return {"go_machine": go_id, "plafond_usd": MONTANT_GO_MACHINE_USD}


